CREATE OR REPLACE VIEW Str_VStore AS
SELECT
       S.Id,  S.Name    , S.Rem,
       St.Id  Status_Id , St.Name  Status_Name,
       Ct.Id  Cost_Id   , Ct.Num   Cost_Num   , Ct.Name  Cost_Name   ,
       Sa.Id  Acc_Id    , Sa.Num   Acc_Num    , Sa.Name  Acc_Name    ,
       Rev.Id Rev_Acc_Id, Rev.Num  Rev_Acc_Num, Rev.Name Rev_Acc_Name,
       Cst.Id Cst_Acc_Id, Cst.Num  Cst_Acc_Num, Cst.Name Cst_Acc_Name,
       S.Emp_Id         , S.Emp_Id Emp_Num    , S.Emp_Id Emp_Name
  FROM Str_Store      S  ,
       Acc_Cost       Ct ,
       Acc_Acc        Sa ,
       Acc_Acc        Rev,
       Acc_Acc        Cst,
       Phs_Cod_Status St
 WHERE IFNULL(S.Cost_Id  ,0)=CT.Id
   AND IFNULL(S.Acc_Id   ,0)=SA.Id
   AND IFNULL(S.RevAcc_Id,0)=REV.Id
   AND IFNULL(S.CstAcc_Id,0)=CST.Id
   AND IFNULL(S.Status_Id,1)=ST.Id;

CREATE OR REPLACE VIEW Str_VDefAcc AS
SELECT
       SS.Id   Stor_Id   , SS.Name    Stor_Name , SS.Rem  Stor_Rem   , SS.Status_Id Stor_Status,
       DF.Id,  DF.Rem    , TP.Id      TrnTyp_Id , TP.Name TrnTyp_Name,
       CT.Id   Cost_Id   , CT.Num     Cost_Num  , CT.Name Cost_Name  ,
       CA.Id   CstAcc_Id , CA.Num     CstAcc_Num, CA.Name CstAcc_Name,
       RA.Id   RevAcc_Id , RA.Num     RevAcc_Num, RA.Name RevAcc_Name
  FROM Str_DefAcc     DF,
       Str_Store      SS,
       Str_Cod_TrnTyp TP,
       Acc_Cost       CT,
       Acc_Acc        CA,
       Acc_Acc        RA
 WHERE DF.Stor_Id  =SS.Id
   AND DF.TrnTyp_Id=TP.Id
   AND DF.CstAcc_Id=CA.Id
   AND DF.RevAcc_Id=RA.Id
   AND SS.Cost_Id  =CT.Id;

CREATE OR REPLACE VIEW Str_VItem AS
