       I.Id , I.Num    , I.Name , I.Rem      ,
       I.Num||' - '||I.Name       FName      ,
       ST.Id  Status_Id, ST.Name  Status_Name,
       UN.Id  Unit_Id  , UN.Name  Unit_Name  ,
       S1.Id  Spc1_Id  , S1.Name  Spc1_Name  ,
       S2.Id  Spc2_Id  , S2.Name  Spc2_Name  ,
       S3.Id  Spc3_Id  , S3.Name  Spc3_Name  ,
       S4.Id  Spc4_Id  , S4.Name  Spc4_Name  ,
       S5.Id  Spc5_Id  , S5.Name  Spc5_Name
  FROM Str_Item        I ,
       Phs_Cod_Status  ST,
       Cpy_Cod_Unit    UN,
       Str_Cod_Spec1   S1,
       Str_Cod_Spec2   S2,
       Str_Cod_Spec3   S3,
       Str_Cod_Spec4   S4,
       Str_Cod_Spec5   S5
 WHERE I.Status_Id=ST.Id
   AND I.Unit_Id  =UN.Id
   AND I.Spc1_Id  =S1.Id
   AND I.Spc2_Id  =S2.Id
   AND I.Spc3_Id  =S3.Id
   AND I.Spc4_Id  =S4.Id
   AND I.Spc5_Id  =S5.Id;

